import openpyxl, csv
from collections import Counter

wb = openpyxl.load_workbook('/app/input_files/portfolio/holdings_2026Q3.xlsx', read_only=True)
# readme sheet content
for ws in wb.worksheets:
    if ws.title in ('readme','q2_roll','contact'):
        print('=== sheet', ws.title)
        for r in ws.iter_rows(values_only=True):
            print(r)

rows=[]
for ws in wb.worksheets:
    if ws.title.startswith('acct_'):
        data=list(ws.iter_rows(values_only=True))
        hdr=data[0]
        for r in data[1:]:
            rows.append(dict(zip(hdr,r)))
print('total holdings rows:', len(rows))
print('as_of values:', Counter(str(r['as_of']) for r in rows))
print('sec_type values:', Counter(r['sec_type'] for r in rows))
# duplicates
key=Counter((r['acct'],r['sec_code'],str(r['vol'])) for r in rows)
dups={k:v for k,v in key.items() if v>1}
print('dup keys:', len(dups), 'extra rows:', sum(v-1 for v in dups.values()))
for k,v in list(dups.items())[:20]: print(' ', k, v)
